// David’s Game World catalog: 100 classic games, all public-domain or generic mechanics with original names and art.
// [id, name, category, minPlayers, maxPlayers, glyph, rules, tip]
const CATALOG_RAW = [
// ---------- Board ----------
['chess','Chess','Board',2,2,'board','Each side has 16 pieces; White moves first. Pieces move by type: pawns forward, knights in an L, bishops diagonally, rooks straight, queens both, kings one square. Castling, en passant and pawn promotion are allowed. Checkmate the enemy king to win; stalemate is a draw.','Control the centre early, develop knights and bishops before the queen, and castle to keep your king safe.'],
['checkers','Checkers','Board',2,2,'disc','Pieces move diagonally forward on dark squares. Jump over an enemy piece to capture it; captures are mandatory and chains must be completed. Reach the far row to become a king that moves both ways. Win by capturing or blocking every enemy piece.','Keep your back row filled as long as you can so the opponent cannot crown kings.'],
['go','Go (9×9)','Board',2,2,'stones','Players place black and white stones on intersections, Black first. A group with no empty neighbouring points is captured. You may not repeat the previous position (ko) or commit suicide. When both players pass, territory plus stones decides the winner; White gets 6.5 points of komi.','Corners are easiest to secure, then edges, then the centre. Two separate eyes keep a group alive.'],
['reversi','Reversi','Board',2,2,'disc','Place a disc so that it sandwiches one or more enemy discs in a line; those discs flip to your colour. If you cannot flip anything you must pass. When neither player can move, the player with more discs wins.','Corners can never be flipped; avoid the squares diagonally next to an empty corner.'],
['c4','Four in a Row','Board',2,2,'disc','Players take turns dropping discs into a seven-column grid. Discs fall to the lowest empty space. The first player to line up four of their discs horizontally, vertically or diagonally wins. A full board is a draw.','The centre column is part of the most possible lines, so claim it early.'],
['ttt','Tic-Tac-Toe','Board',2,2,'grid3','Players take turns marking X or O in a 3×3 grid. Three of your marks in a row, column or diagonal wins. If the grid fills with no line, the game is a draw.','Taking the centre or a corner first gives the most winning chances.'],
['gomoku','Gomoku','Board',2,2,'stones','Players alternately place stones on a 15×15 board, Black first. The first player to make an unbroken line of five or more stones in any direction wins.','An open three (three in a row with both ends empty) forces your opponent to respond.'],
['mancala','Mancala','Board',2,2,'pegs','Pick up all seeds from one of your pits and sow them one by one counter-clockwise, skipping your opponent\'s store. Ending in your own store earns another turn. Ending in an empty pit on your side captures the seeds opposite. When one side is empty, the other side\'s seeds go to its owner; most seeds wins.','Count seeds to land exactly in your store and chain extra turns.'],
['dots','Dots and Boxes','Board',2,2,'grid3','Players take turns drawing a line between two neighbouring dots. Completing the fourth side of a box claims it and earns another turn. When every line is drawn, the player with more boxes wins.','Avoid drawing the third side of a box; late in the game, sacrifice short chains to win long ones.'],
['nim','Nim','Board',2,2,'pegs','Several rows of sticks are on the table. On your turn take any number of sticks from a single row. The player who takes the last stick wins.','Leave a position where the binary XOR of all row sizes is zero.'],
['hex','Hex','Board',2,2,'tiles','Players place stones on a 9×9 rhombus of hexagons. Red tries to connect top and bottom; Blue tries to connect left and right. There are no draws; the first connected chain wins.','Two-bridge shapes (two stones with two shared empty neighbours) cannot be cut.'],
['morris','Nine Men\'s Morris','Board',2,2,'pegs','Each player places nine pieces on the 24 points, then moves them along lines to adjacent points. Forming a mill (three in a line) lets you remove an enemy piece not in a mill. With three pieces left you may fly anywhere. Reduce your opponent to two pieces or leave them unable to move to win.','Build positions where one move can open and close a mill repeatedly.'],
['uttt','Ultimate Tic-Tac-Toe','Board',2,2,'grid3','Nine small tic-tac-toe boards form one big board. The cell you play in sends your opponent to the matching small board. Winning a small board claims that square of the big board. Win three big squares in a row to win.','Think about where you are sending your opponent, not just where you are playing.'],
['seabattle','Sea Battle','Board',2,2,'ship','Each player has a hidden fleet of five ships on a 10×10 grid. Take turns calling a square to fire at. You are told hit or miss, and when a ship sinks. Sink the whole enemy fleet first to win.','After a hit, test the neighbouring squares; when hunting, a checkerboard pattern covers the grid fastest.'],
['ladders','Snakes & Ladders','Board',2,4,'board','Players roll a die and move along squares 1 to 100. Landing at the foot of a ladder climbs it; landing on a snake\'s head slides you down. You must not go past 100. The first to reach exactly 100 wins.','It is pure luck, so enjoy the ride and cheer for ladders.'],
['backgammon','Backgammon','Board',2,2,'board','Each player moves 15 checkers around 24 points according to two dice. A single checker can be hit and sent to the bar. Once all your checkers are in your home board you may bear them off. The first to bear off all checkers wins.','Make points (two or more checkers) in your home board to trap enemy checkers on the bar.'],
['chinesecheckers','Chinese Checkers','Board',2,6,'stones','Two to six players each start with ten pegs in one point of a six-pointed star and race them into the point directly opposite. On your turn move one peg: step to an empty neighbouring hole, or hop over any single peg (yours or anyone’s) into the empty hole just beyond, and keep chaining hops as long as you can. Pegs are never captured. The first player to fill the opposite point wins. If a blocker sits in your target point, you win once every hole there is filled and at least one is yours.','Build ladders of pegs you can hop along, and don’t leave your last peg behind.'],
['starcheckers','Star Checkers','Board',2,2,'stones','Two players race ten pegs each across a six-pointed star board to the opposite point. A peg steps to an adjacent hole or hops over any peg into the empty hole beyond, chaining as many hops as it likes. The first player to fill the opposite point wins; a point blocked by enemy pegs still counts once it is full and holds one of yours.','Build ladders of pegs that let you chain long hops.'],
['xiangqi','Xiangqi','Board',2,2,'board','Pieces move on intersections of a 9×10 board split by a river. Generals stay in their palace and may not face each other directly. Cannons capture by jumping exactly one piece. Checkmate the enemy general to win.','Cannons are strongest early; horses and chariots grow stronger as the board opens.'],
['shogi','Shogi','Board',2,2,'board','Players move pieces on a 9×9 board; most pieces promote on reaching the far three ranks. Captured pieces switch sides and can be dropped back onto the board as your own. Checkmate the enemy king to win.','Keep captured pieces in hand: a well-timed drop is often decisive.'],
['ludo','Ludo','Board',2,4,'board','Roll a six to bring a token out of your yard. Move tokens around the track by the die roll; landing on an opponent sends their token home. Get all four tokens to your home column first.','Spread risk across tokens and avoid stopping just ahead of an opponent.'],
['foxgeese','Fox & Geese','Board',2,2,'pegs','Thirteen geese face one fox on a cross-shaped board. Geese move one step forward or sideways; the fox moves one step in any straight direction and captures by jumping, chaining jumps. The geese win by trapping the fox; the fox wins when only four geese remain.','Geese should advance in a solid line with no gaps.'],
['halma','Halma','Board',2,2,'stones','Each player starts with 15 pieces in a corner camp of a 10×10 board. Move a piece to any adjacent square, or jump over a neighbouring piece and keep jumping. The first to move every piece into the opposite camp wins.','Leave stepping-stone pieces behind for long jump chains.'],
['senet','Senet','Board',2,2,'board','An ancient race game on a 3×10 board. Throw four sticks (1–5) and move a piece forward along the S-shaped path; throws of 1, 4 and 5 earn another throw. Landing on a lone enemy swaps places; pairs are protected and three in a row block. The 27th square is water and sends a piece back. Bear off all five pieces with exact throws to win.','Keep pieces in pairs: paired pieces cannot be attacked.'],
['ur','Royal Game of Ur','Board',2,2,'board','Each player races seven pieces along a shared track using four binary dice. Landing on an enemy piece in the shared lane sends it back. Rosette squares grant another roll and are safe. Bring all pieces home to win.','The central rosette is the strongest square on the board; hold it.'],
['tafl','Hnefatafl','Board',2,2,'board','Attackers surround a king and his defenders. All pieces move like rooks. Sandwich an enemy between two of yours to capture. The king escapes to a corner to win for the defenders; capturing the king wins for attackers.','Attackers should block the corners first; defenders should open lines quickly.'],
['dominoes','Dominoes','Board',2,4,'tiles','Each player draws tiles and in turn matches one end of a tile to an open end of the line. If you cannot play you draw from the boneyard, then pass. The first to empty their hand wins; if the game blocks, the lowest pip count wins.','Play heavy tiles early so you are not caught holding them.'],
['alquerque','Alquerque','Board',2,2,'pegs','On a 5×5 grid of lines, pieces move to adjacent empty points along lines and capture by jumping. Multiple captures in one turn are allowed. Capture all enemy pieces to win.','It is the ancestor of checkers; avoid leaving gaps behind pieces.'],
['intdraughts','International Draughts','Board',2,2,'disc','Played on a 10×10 board with 20 pieces each. Men capture forwards and backwards and the maximum capture is compulsory. Kings fly any distance diagonally. Capture or block all enemy pieces to win.','Count the longest capture sequence before every move, for both sides.'],
['lines','Lines of Action','Board',2,2,'disc','Each piece moves in a straight line exactly as many squares as there are pieces on that line. You may jump your own pieces and capture by landing on enemies. The first player to connect all their pieces into one group wins.','Centralise early: connected pieces in the middle are hard to split.'],
['konane','Kōnane','Board',2,2,'stones','A Hawaiian jumping game played on a full board of alternating stones. After two stones are removed, players must jump an enemy stone orthogonally into an empty space each turn. The first player unable to move loses.','Count available jumps for both sides; tempo decides the endgame.'],
// ---------- Card ----------
['klondike','Klondike Solitaire','Card',1,1,'cards','Build four foundations from Ace to King by suit. In the seven tableau columns, stack cards in descending order with alternating colours. Only Kings may fill empty columns. Turn cards from the stock when stuck. Move every card to the foundations to win.','Uncover face-down cards in the longest columns first.'],
['crazy8','Crazy Eights','Card',2,5,'cards','Match the top discard by suit or rank. Eights are wild and let you name the next suit. If you cannot play you draw up to three cards, then pass. The first player to empty their hand wins.','Save your eights for when you are stuck, and steer the suit to one you hold many of.'],
['war','War','Card',2,2,'cards','The deck is split evenly. Both players flip their top card; the higher card takes both. On a tie it is war: each places three cards face down and one face up, and the higher card takes all. Take every card to win.','No decisions, just suspense: a great game for quick fun.'],
['blackjack','Blackjack','Card',1,1,'cards','Get closer to 21 than the dealer without going over. Number cards count face value, faces count 10 and Aces count 1 or 11. Hit to take a card, stand to stop, double to double your bet for one card. The dealer draws to 17. Blackjack pays 3 to 2.','Stand on 12–16 when the dealer shows 2–6; hit when the dealer shows 7 or higher.'],
['freecell','Free Cell','Card',1,1,'cards','All cards are dealt face up into eight columns. Four free cells each hold one card. Build foundations by suit from Ace to King and tableau columns down in alternating colours.','Keep free cells empty as long as possible; they are your working space.'],
['spider','Spider Solitaire','Card',1,1,'cards','Build complete runs from King down to Ace in the same suit inside the tableau; full runs are removed. Deal a new row from the stock when stuck. Clear all cards to win.','Empty columns are precious; use them to rearrange long runs.'],
['hearts','Hearts','Card',4,4,'cards','Four players pass three cards, then play 13 tricks following suit when possible. The 2 of clubs leads; hearts cannot be led until broken. Each heart costs one point and the Queen of Spades 13; taking all of them (shooting the moon) gives 26 to everyone else. When someone reaches 100, the lowest score wins.','Pass high spades and hearts early; void a suit to dump penalty cards.'],
['spades','Spades','Card',4,4,'cards','Two partnerships bid how many tricks they will take; a nil bid promises none. Players follow suit; spades are always trump and cannot be led until broken. Making your bid scores ten per trick plus one per extra trick (bags); ten bags cost 100. The first team to 300 wins.','Count spades played; the last trumps control the end of each hand.'],
['holdem','Texas Hold\'em','Card',2,6,'cards','Each player gets two private cards and shares five community cards. Betting rounds follow the deal, flop, turn and river; you can fold, check, call or raise. Make the best five-card hand or make everyone else fold. Blinds rise every eight hands; the last player with chips wins.','Position matters: acting last lets you see what everyone else does.'],
['ginrummy','Gin Rummy','Card',2,2,'cards','Each player holds ten cards and draws then discards each turn. Form sets of the same rank and runs in the same suit. Knock when your unmatched cards are 10 or less, or go gin with none.','Watch your opponent\'s discards to guess what they are collecting.'],
['bridge','Contract Bridge','Card',4,4,'cards','Two partnerships bid for a contract naming tricks and a trump suit. Declarer plays both their own hand and their partner\'s exposed dummy. Making the contract scores points; failing gives points to the defenders. Four deals are played; the higher total wins.','Communicate through standard bids and count the high-card points.'],
['euchre','Euchre','Card',4,4,'cards','Played with 24 cards by two partnerships. The jack of trump (right bower) and the other jack of the same colour (left bower) are the highest trumps. The team that orders up or names trump must take three of five tricks, or the defenders score two. First to ten points wins.','Lead trump when your team called it; save the bowers for key tricks.'],
['cribbage','Cribbage','Card',2,2,'cards','Each player discards two cards to the dealer\'s crib, then a starter is cut. Play cards in turn, scoring for fifteens, thirty-ones, pairs, runs and the go. Then hands and the crib are scored for fifteens, pairs, runs, flushes and nobs. First to 121 wins.','Keep cards that combine to fifteen, and give your opponent\'s crib awkward cards.'],
['oldmaid','Old Maid','Card',2,6,'cards','One queen is removed so one card cannot be paired. Players discard pairs, then draw blindly from the next player\'s hand, discarding any new pairs. The first player out wins; whoever is left holding the last queen is the Old Maid.','Shuffle your hand often so no one can track the odd card.'],
['gofish','Go Fish','Card',2,6,'cards','Ask another player for a rank you hold. If they have it they hand it over and you ask again; otherwise go fish from the deck. Collect books of four. Most books wins.','Remember who asked for what: that tells you what they hold.'],
['pyramid','Pyramid Solitaire','Card',1,1,'cards','Cards form a pyramid. Remove pairs of uncovered cards that add to 13; Kings are removed alone. Use the stock to find matches. Clear the pyramid to win.','Prioritise freeing cards that cover many others.'],
['golf','Golf Solitaire','Card',1,1,'cards','Seven columns of five cards. Move the top card of any column onto the waste if it is one rank higher or lower. Turn the stock when stuck. Clear all columns to win.','Plan long chains up and down before playing.'],
['president','President','Card',3,6,'cards','Players shed cards by playing a higher set of the same size as the previous play, or pass. When everyone passes, the last player to play leads again. Finishing order sets ranks for the next hand, when the lowest player gives the President their two best cards. After three hands, most points wins. 3 is low and 2 is high.','Hold twos and pairs for control late in the hand.'],
['slapjack','Slapjack','Card',1,1,'cards','You and the computer take turns flipping cards onto a central pile. When a Jack appears, slap first to take the whole pile. Slap the wrong card and you give one away. Win all the cards, or hold the most when time runs out.','Pure reflexes: stay focused on every flip.'],
['baccarat','Baccarat','Card',1,1,'cards','Bet on Player, Banker or Tie. Two hands are dealt and drawn by fixed rules; a hand\'s value is the last digit of its total. The hand closest to nine wins. Player pays even money, Banker 0.95 to 1, Tie 8 to 1.','The Banker bet has the lowest house edge.'],
// ---------- Dice ----------
['yacht','Yacht','Dice',1,4,'dice','Roll five dice up to three times per turn, holding any between rolls. Then score the roll in one unused category such as Threes, Full House or Straight. Each category is used once. A bonus of 35 is earned for 63 or more in the upper section. Highest total wins.','Chase the upper-section bonus early; keep Chance as a safety net.'],
['pig','Pig','Dice',2,4,'dice','On your turn roll a die as many times as you like, adding each roll to your turn total. Rolling a 1 loses the turn total and ends your turn. Hold to bank the total. First to 100 wins.','Holding at around 20 points is a strong simple strategy.'],
['liars','Liar\'s Dice','Dice',2,6,'dice','Everyone rolls five dice in secret. Players bid on how many dice of a face are showing among all players, each bid higher than the last; ones are wild. Call liar to challenge: if the bid was wrong the bidder loses a die, otherwise the caller does. The last player with dice wins.','Base bids on your own dice plus the expected number in other cups.'],
['farkle','Farkle','Dice',2,6,'dice','Roll six dice and set aside scoring dice: ones, fives and three of a kind or better. Keep rolling the rest or bank your points; scoring with all six gives hot dice. Rolling no scoring dice loses the turn\'s points. First to 5,000 wins.','Bank early with few dice left; the risk of a farkle rises fast.'],
['shipcap','Ship, Captain & Crew','Dice',2,6,'dice','Roll five dice up to three times. You must set aside a 6 (ship), then a 5 (captain), then a 4 (crew), in that order. The two remaining dice are your cargo, which you may reroll while rolls remain. Highest total cargo over three rounds wins.','Once you have ship, captain and crew, reroll low cargo dice.'],
['mexico','Mexico','Dice',2,6,'dice','Roll two dice; the higher die is the tens digit. 21 (Mexico) is best, then doubles, then high numbers. The round leader sets how many rolls everyone may use. The lowest roll loses a life (two if Mexico was rolled). The last player with lives wins.','Stopping after one good roll limits everyone else to one roll too.'],
// ---------- Puzzle ----------
['sudoku','Sudoku','Puzzle',1,1,'grid3','Fill the 9×9 grid so every row, column and 3×3 box contains the digits 1 to 9 exactly once. Some digits are given. Each puzzle has one solution.','Scan for cells where only one digit fits, and use pencil marks for harder puzzles.'],
['mines','Mine Sweep','Puzzle',1,1,'grid3','Reveal every safe square without hitting a mine. Each number shows how many mines touch that square. Flag squares you know are mines. Your first click is always safe.','When a number already touches enough flags, all its other neighbours are safe.'],
['g2048','2048','Puzzle',1,1,'tiles','Slide all tiles in one direction. Two tiles with the same number merge into their sum. A new tile appears after every move. Reach the 2048 tile; the game ends when no move is possible.','Keep your largest tile in a corner and build towards it in one row.'],
['fifteen','15 Puzzle','Puzzle',1,1,'tiles','Slide the numbered tiles into the empty space. Arrange them in order from 1, left to right and top to bottom, with the gap last.','Solve the top row and left column first, then repeat on the smaller puzzle.'],
['lightsout','Lights Off','Puzzle',1,1,'grid3','Pressing a light toggles it and its four neighbours. Turn every light off in as few presses as possible.','Chase lights downward row by row, then use the bottom pattern to fix the top.'],
['peg','Peg Solitaire','Puzzle',1,1,'pegs','Jump a peg over an adjacent peg into an empty hole; the jumped peg is removed. Only straight jumps are allowed. Finish with as few pegs as possible; one peg in the centre is perfect.','Work in blocks of three and avoid stranding pegs in the corners.'],
['codebreaker','Code Breaker','Puzzle',1,1,'pegs','Guess the hidden code of coloured pegs. After each guess you see how many pegs are the right colour in the right place (dark) and the right colour in the wrong place (light). Crack it within ten guesses.','Use early guesses to learn which colours are present.'],
['memory','Memory Match','Puzzle',1,1,'cards','All cards start face down. Turn over two per turn; matching pairs stay up. Find every pair with as few misses as possible.','Turn an unknown card first, then use memory for the second.'],
['hanoi','Tower of Hanoi','Puzzle',1,1,'blocks','Move the whole stack of disks to another peg. Move one disk at a time and never place a larger disk on a smaller one. Fewest moves wins.','The smallest disk moves every other turn, always in the same circular direction.'],
['nonogram','Picture Cross','Puzzle',1,1,'grid3','Number clues beside each row and column give the lengths of filled runs, in order. Fill cells to satisfy every clue and reveal the picture.','Start with big clues: overlapping runs must be filled.'],
['kakuro','Kakuro','Puzzle',1,1,'grid3','Fill white cells with digits 1 to 9 so each run adds up to its clue. No digit may repeat within a run.','Learn unique combinations, such as 3 in two cells being 1 and 2.'],
['cagesums','Cage Sums','Puzzle',1,1,'grid3','Fill the grid so each row and column has each digit once. Outlined cages show a target and an operation; the digits in the cage must produce it.','Single-cell cages are free digits; start there.'],
['sokoban','Crate Pusher','Puzzle',1,1,'blocks','Push every crate onto a target square. You can push but never pull, one crate at a time. Every level is generated to be solvable.','Never push a crate into a corner that is not a target.'],
['tilematch','Tile Match Solitaire','Puzzle',1,1,'tiles','Remove pairs of matching free tiles from a stacked layout. A tile is free when nothing covers it and its left or right side is open. Clear all tiles to win; every layout can be solved.','Free tiles that unlock the most others first.'],
['jigsaw','Jigsaw','Puzzle',1,1,'tiles','The picture is cut into square pieces and shuffled. Swap pieces until the picture is complete.','Sort pieces by colour before assembling the interior.'],
['maze','Maze Escape','Puzzle',1,1,'maze','Find a route from the entrance to the exit through the maze before time runs out.','Keep one hand on a wall: in simple mazes it always leads out.'],
['tangram','Tangram','Puzzle',1,1,'tiles','Use all seven shapes, without overlap, to fill the silhouette shown. Drag pieces, tap to turn them and double-tap the parallelogram to flip it.','Place the two large triangles first; they decide most shapes.'],
['bubbles','Bubble Pop','Puzzle',1,1,'ball','Aim and shoot coloured bubbles at the cluster. Three or more of one colour pop; unsupported bubbles fall. Clear the board before it reaches the bottom.','Bounce shots off the walls to reach tight spots.'],
['gemswap','Gem Swap','Puzzle',1,1,'tiles','Swap two neighbouring gems to make a line of three or more of one colour. Matches clear and new gems fall. Score as many points as you can.','Work near the bottom to trigger falling chain reactions.'],
['flowlink','Pipe Link','Puzzle',1,1,'maze','Rotate pipe tiles so water flows from the source to every outlet with no leaks.','Corner and edge tiles have the fewest valid rotations; fix them first.'],
// ---------- Word ----------
['hangman','Hangman','Word',1,1,'letters','Guess the hidden word one letter at a time. Each wrong guess adds a piece to the drawing. Reveal the whole word before the drawing is complete.','Try common vowels first, then R, S, T, L and N.'],
['five','Five Letters','Word',1,1,'letters','Guess the hidden five-letter word in six tries. After each guess, green means the right letter in the right place, yellow means the letter is in the word elsewhere, and grey means it is not in the word.','Start with a word using several vowels and common consonants.'],
['scramble','Word Scramble','Word',1,1,'letters','A word\'s letters are shuffled. Unscramble them before the timer ends; faster answers score more and hints cost points. Ten rounds per game.','Look for common endings like -ING, -ED and -ER.'],
['lettergrid','Letter Grid','Word',1,1,'letters','Find words by linking neighbouring letters in the grid, using each letter once per word, within three minutes. Words need three or more letters; longer words score more. Beat the computer\'s total to win.','Hunt for plural and -ED forms of words you already found.'],
['wordtiles','Word Tiles','Word',2,4,'letters','Draw seven letter tiles and form words on the board, crossing or touching existing words; the first word covers the centre star. Letter values and bonus squares set scores, and using all seven tiles earns 50 more. The game ends when the bag and one rack are empty; highest score wins.','Two-letter words help you fit tiles in tight spots.'],
['crossword','Crossword','Word',1,1,'letters','Fill the grid with answers to the across and down clues. Crossing letters must agree. Check your work at any time or reveal a letter if you are stuck.','Fill short, easy answers first to get crossing letters.'],
['wordsearch','Word Search','Word',1,1,'letters','Find the listed words hidden in a grid of letters, forwards, backwards or diagonally.','Scan for unusual letters like Q, X or Z from the word list.'],
['ghost','Ghost','Word',2,6,'letters','Players add one letter at a time to a growing fragment. Completing a word of four or more letters, or being caught adding a letter no word can follow, earns a letter of G-H-O-S-T. You may challenge the previous player. Spell GHOST and you are out; the last player standing wins.','Steer towards long words where your opponent will have to finish.'],
// ---------- Arcade ----------
['snake','Snake','Arcade',1,1,'snake','Steer the snake to eat food. Each bite makes it longer. Hitting a wall or your own tail ends the game.','Hug the edges in long sweeps and leave yourself an escape lane.'],
['blocks','Falling Blocks','Arcade',1,1,'blocks','The classic block-stacking game. Shapes made of four square blocks fall into the well. Move and rotate them to fill complete rows, which clear for points; clear several rows at once for a bigger score. The game ends when the stack reaches the top.','Keep the surface flat and leave one column open for the long four-block piece.'],
['beads','Bead Drop','Arcade',1,1,'pegs','A softer twist on falling blocks. Clusters of two, three or four round beads drop into a wide well, with a guide showing where they will land. Fill complete rows to clear them. The game ends when the beads reach the top.','The small two-bead pieces are perfect for patching single gaps.'],
['breaker','Brick Breaker','Arcade',1,1,'ball','Move the paddle to bounce the ball into the bricks. Clear every brick to finish a wall. Missing the ball costs a life.','Hitting with the paddle edge sends the ball at a sharper angle.'],
['paddle','Paddle Ball','Arcade',1,1,'ball','Two paddles volley a ball. Miss the ball and your opponent scores. First to 7 points wins.','Move back to the middle after each return.'],
['invaders','Star Defender','Arcade',1,1,'star','Rows of alien ships march down the screen. Slide your cannon and shoot them before they land. Dodge enemy fire. Clear a wave to face a faster one.','Clear the outer columns first; the formation then takes longer to reach the edges.'],
['hopper','Sky Hopper','Arcade',1,1,'ball','Tap to flap upward; gravity pulls you down. Fly through the gaps between columns. Touching a column or the ground ends the run.','Tap in small, steady rhythms instead of big bursts.'],
['echo','Color Echo','Arcade',1,1,'target','Watch the coloured pads light up in sequence, then repeat it. Each round adds one step. A mistake ends the game.','Say the colours out loud or group them in threes.'],
['whack','Whack-a-Mole','Arcade',1,1,'hole','Moles pop out of holes for a moment. Tap them before they hide. Misses cost points. Score as much as you can before time runs out.','Rest your eyes in the centre so you see every hole at once.'],
['trails','Light Trails','Arcade',1,1,'snake','Two light cycles leave walls behind them. Steer to avoid every wall, including your own. The last rider moving wins the round; best of five.','Cut off open space from your rival and keep a large area for yourself.'],
['rockblaster','Rock Blaster','Arcade',1,1,'star','Pilot a ship that rotates and thrusts in space. Shoot drifting rocks; big rocks split into smaller ones. Avoid collisions.','Stay near the centre and let rocks come to you.'],
['roadhop','Road Hopper','Arcade',1,1,'car','Hop across lanes of traffic, then ride the floating logs over the river to fill the five homes at the top. Getting hit or falling in the water costs a life.','Wait for a gap rather than rushing every lane.'],
['lander','Moon Lander','Arcade',1,1,'star','Rotate and fire your thruster to land gently on the yellow pad before your fuel runs out. Touch down slowly and level to score, then try the next landing.','Kill horizontal speed first, then control the descent.'],
['citydefense','City Defense','Arcade',1,1,'target','Missiles fall towards your cities. Tap the sky to launch interceptors that explode and destroy missiles caught in the blast. Protect at least one city to keep going.','Aim ahead of fast missiles; one blast can stop several.'],
['minigolf','Mini Golf','Arcade',1,1,'ball','Drag back from the ball and release to putt through each hole\'s obstacles. Par is three per hole; finish under par for the best score.','Use banks off walls instead of aiming straight at the hole.'],
// ---------- Party ----------
['rps','Rock Paper Scissors','Party',2,2,'target','Both players pick rock, paper or scissors at the same time. Rock beats scissors, scissors beats paper, paper beats rock. First to three round wins takes the match.','People repeat winning throws; switch after a loss.'],
['trivia','Quick Trivia','Party',1,1,'letters','Answer ten multiple-choice questions before the timer runs out, against computer rivals. Faster correct answers earn more points. Finish on top to win.','Eliminate obviously wrong answers first.'],
// ---------- Third wave ----------
['ttt4','Tic-Tac-Toe 4×4','Board',2,2,'grid3','Players take turns marking a 4×4 grid. Four of your marks in a row, column or diagonal wins. A full grid is a draw.','Block early: with four needed, the centre squares matter most.'],
['misere','Misère Tic-Tac-Toe','Board',2,2,'grid3','Played like tic-tac-toe, but whoever completes three in a row loses. If the grid fills with no line, it is a draw.','Take the centre and mirror your opponent through it.'],
['connect5','Connect Five','Board',2,2,'disc','Drop discs into a nine-column grid; they fall to the lowest space. Line up five of your colour in any direction to win.','Build threats on two rows at once so one drop cannot block both.'],
['reversi6','Reversi 6×6','Board',2,2,'disc','Reversi on a smaller board. Place a disc to sandwich enemy discs in a line and flip them. Pass when you cannot move. Most discs at the end wins.','On a small board, corners are worth even more.'],
['oware','Oware','Board',2,2,'pegs','Pick up all seeds from one of your six pits and sow them counter-clockwise, skipping the starting pit. If your last seed makes a pit on the opponent\'s side hold 2 or 3, capture it and any such pits before it. You must leave the opponent seeds to play. Capture more than 24 to win.','Hoard seeds in one pit for a big sowing that reaches far into the opponent\'s side.'],
['russian','Russian Draughts','Board',2,2,'disc','Draughts on 8×8. Men move forward but capture forwards and backwards; captures are compulsory. Kings fly any distance diagonally. Capture or block every enemy piece to win.','Flying kings are deadly: keep long diagonals closed.'],
['giveaway','Giveaway Checkers','Board',2,2,'disc','Checkers played backwards: captures are still compulsory, but the first player to lose all pieces, or have no moves, wins.','Offer pieces where your opponent is forced to take them.'],
['chess960','Chess960','Board',2,2,'board','Chess with the back-rank pieces shuffled: bishops on opposite colours and the king between the rooks. Black mirrors White. Normal chess rules apply, except that this version does not use castling.','Opening theory is gone: think about piece activity from move one.'],
['koth','King of the Hill','Board',2,2,'board','Normal chess rules, plus a second way to win: move your king to one of the four centre squares.','The king becomes an attacker; centralise it once the queens are gone.'],
['threecheck','Three-Check Chess','Board',2,2,'board','Normal chess, but giving check three times also wins the game.','Every check counts: keep pieces ready to deliver quick checks.'],
['antichess','Antichess','Board',2,2,'board','The aim is to lose all your pieces. Captures are compulsory, the king is an ordinary piece, there is no check, and pawns may promote to kings. A player with no pieces or no moves wins.','Force your opponent into long capture chains while keeping your own options open.'],
['atarigo','Capture Go','Board',2,2,'stones','A beginner\'s Go on a 9×9 board: the first player to capture any stone wins. Stones are captured when their group has no empty neighbouring points.','Count liberties: a group with one liberty left is in atari.'],
['go13','Go (13×13)','Board',2,2,'stones','Go on a medium 13×13 board. Surround territory and capture stones; when both players pass, stones plus surrounded territory are counted, with 6.5 komi for White.','Corners first, then sides: the 13×13 board rewards balance.'],
['hex11','Hex 11×11','Board',2,2,'tiles','Hex on the classic 11×11 board. Red connects top and bottom, Blue connects left and right. There are no draws.','Play close to the centre early, then use two-bridges to stay connected.'],
['morris3','Three Men\'s Morris','Board',2,2,'pegs','Each player has three pieces. Place them in turn on the nine points, then move a piece to an adjacent point along a line. Three in a row wins.','Taking the centre point first is a big advantage.'],
['morris6','Six Men\'s Morris','Board',2,2,'pegs','Each player has six pieces on a board of two squares. Place them, then move them along lines. A mill (three in a line) removes an enemy piece. Reduce the opponent to two pieces or leave them unable to move.','The connecting midpoints control both squares.'],
['morris12','Twelve Men\'s Morris','Board',2,2,'pegs','Nine Men\'s Morris with twelve pieces each and extra diagonal lines that also form mills. If the board fills during placement, the game is drawn.','Diagonal mills appear from unexpected angles; watch the corners.'],
['achi','Achi','Board',2,2,'pegs','A Ghanaian game on a 3×3 grid with diagonals. Each player places four pieces, then slides them along lines to the single empty point. Three in a row wins.','With one empty point, every move is forced: plan two moves ahead.'],
['misenim','Misère Nim','Board',2,2,'pegs','Take any number of sticks from one row. Whoever takes the very last stick loses.','Play normal Nim until only rows of one remain, then leave an odd number.'],
['subtract','Subtraction Game','Board',2,2,'pegs','Twenty-one sticks. On your turn take one, two or three. Whoever takes the last stick wins.','Always leave a multiple of four.'],
['ataxx','Infection','Board',2,2,'disc','Move a piece one square in any direction to clone it, or two squares to jump. Enemy pieces next to where you land turn to your colour. When the board fills or nobody can move, most pieces wins.','Clone rather than jump early; jumping leaves holes behind.'],
['breakthrough','Breakthrough','Board',2,2,'disc','Each side has two rows of pieces. Move one square straight or diagonally forward; capture only diagonally. The first piece to reach the far row wins.','Keep a solid back line and attack in a phalanx.'],
['pente','Capture Five','Board',2,2,'stones','Place stones on a 13×13 board. Sandwiching exactly two enemy stones between yours captures them. Win with five in a row or five captured pairs.','Watch for pairs: two of your stones in a row can be captured.'],
['connect6','Connect6','Board',2,2,'stones','Black opens with one stone; after that each player places two stones per turn on a 15×15 board. Six in a row wins.','Two stones per turn means threats must be double-blocked.'],
['fences','Fences','Board',2,2,'maze','Race your pawn to the far side of a 9×9 board. On your turn, move one square or place one of your ten walls to slow your opponent. You may jump an adjacent pawn. A wall may never cut off a pawn\'s last path.','Save walls for the end, when they cost your opponent the most.'],
['amazons','Amazons','Board',2,2,'board','Each player has four queens on a 10×10 board. On your turn move a queen like a chess queen, then shoot an arrow from it in a queen line to block a square forever. The last player able to move wins.','Fight for open space and use arrows to wall off territory.'],
['clobber','Clobber','Board',2,2,'stones','The board starts full of alternating stones. Move one of your stones onto an orthogonally adjacent enemy stone, which is removed. The last player who can move wins.','Avoid isolating your own stones; they become useless.'],
['domineering','Domineering','Board',2,2,'tiles','Players place dominoes on an 8×8 grid: one always vertically, the other horizontally. The last player able to place wins.','Create spaces only your orientation can fill.'],
['ponghauki','Pong Hau K\'i','Board',2,2,'pegs','A tiny Chinese game with five points and two pieces each. Slide a piece along a line into the empty point. A player who cannot move loses.','Avoid moving into the corners where you can be trapped.'],
['hareandhounds','Hare and Hounds','Board',2,2,'pegs','Three hounds try to trap one hare on an eleven-point board. Hounds may move forward or sideways but never back; the hare moves freely. The hare wins by slipping behind the hounds or surviving 60 moves.','Hounds should advance together in a line.'],
['tablut','Tablut','Board',2,2,'board','A tafl game on a 9×9 board. All pieces move like rooks; sandwich an enemy piece to capture it. The defenders win when the king reaches any edge; attackers win by surrounding him on four sides.','Attackers must close the edges early; defenders must open lines fast.'],
['brandubh','Brandubh','Board',2,2,'board','A small Irish tafl game on 7×7. The king escapes to a corner to win; attackers win by surrounding him on four sides. Pieces move like rooks and capture by sandwiching.','With so few pieces, every capture changes the game.'],
['hasami','Hasami Shogi','Board',2,2,'board','Nine pieces each start on opposite back rows of a 9×9 board. Pieces move like rooks. Sandwich enemy pieces in a straight line to capture them. Reduce your opponent to three pieces to win.','Keep pieces in pairs so they cannot be sandwiched.'],
['sim','Sim','Board',2,2,'target','Six dots are joined by fifteen lines. Players take turns colouring a line. Whoever first completes a triangle entirely in their own colour loses.','Spread your lines out so no two share a dot with a third.'],
['whist','Whist','Card',4,4,'cards','Two partnerships play thirteen tricks. The dealer\'s last card sets trump. Follow suit when you can. Each trick over six scores a point for the team; first to five points wins.','Lead from your longest suit and count the trumps played.'],
['ohhell','Oh Hell','Card',3,5,'cards','Seven rounds with hand sizes from seven down to one. A turned card sets trump. Bid exactly how many tricks you will take; the dealer may not make the bids add up to the number of cards. Hitting your bid scores ten plus the bid.','Low cards can be as valuable as high ones when you bid zero.'],
['knockout','Knock-Out Whist','Card',2,6,'cards','Each round deals one fewer card, starting at seven. A turned card sets trump and players follow suit. Anyone taking no tricks is knocked out. The last player standing wins.','Save a trump for the small final rounds.'],
['durak','Durak','Card',2,4,'cards','Played with 36 cards; a trump suit is turned. The attacker plays cards and the defender must beat each one with a higher card of the same suit or a trump, or pick them all up. Attackers may add cards of ranks already on the table. Everyone refills to six. Whoever is left holding cards is the durak.','Keep trumps for defence and attack with low cards early.'],
['cheat','Cheat','Card',3,6,'cards','Players take turns placing one to four cards face down, claiming they are the next rank in sequence. Anyone may call cheat: a liar takes the pile, otherwise the caller does. First to empty their hand wins.','Tell the truth when you can; bluff when nobody can easily check.'],
['beggar','Beggar-My-Neighbour','Card',2,2,'cards','Players turn cards onto a pile. A jack, queen, king or ace demands 1, 2, 3 or 4 cards from the opponent; if those contain no face card or ace, the demander takes the pile. Win all the cards.','No decisions, just suspense: enjoy the swings.'],
['scopa','Scopa','Card',2,2,'cards','Italian fishing game with forty cards. Play a card to capture a table card of the same value, or several that add up to it. Sweeping the table is a scopa. Points go for most cards, most diamonds, the seven of diamonds, most sevens and each scopa. First to 11 wins.','Avoid leaving a table total of ten or less for your opponent to sweep.'],
['briscola','Briscola','Card',2,2,'cards','Forty-card trick game. A trump card is turned under the deck. You need not follow suit. The higher card of the led suit or any trump wins. Aces and threes are worth most; over 60 of the 120 points wins.','Throw low cards on tricks you cannot win and save trumps for valuable tricks.'],
['scat','Thirty-One','Card',2,6,'cards','Hold three cards and draw and discard to make the highest total in one suit, with aces worth 11. Anyone may knock instead of drawing; everyone else gets one more turn. The lowest hand loses a life. Exactly 31 ends the hand at once.','Commit to one suit quickly and knock while others are still building.'],
['sixgolf','Six-Card Golf','Card',2,4,'cards','Each player has six cards in two rows, two face up. On your turn draw and swap with any card, or discard and flip one. When someone\'s cards are all face up, everyone gets one more turn. Kings score 0, matching columns score 0. Lowest total over four holes wins.','Pairs in a column are worth chasing; kings are gold.'],
['yukon','Yukon','Card',1,1,'cards','Like Klondike, but there is no stock: all cards are dealt to seven columns. Any face-up card can be moved together with everything on top of it. Build down in alternating colours and up by suit on the foundations.','Uncover face-down cards as fast as possible.'],
['scorpion','Scorpion','Card',1,1,'cards','Seven columns of seven cards, some face down, plus three reserve cards. Move any face-up card with everything on it onto the next higher card of the same suit. Kings go into empty columns. Build each suit from king to ace in place.','Free the face-down cards in the first four columns early.'],
['canfield','Canfield','Card',1,1,'cards','A reserve of thirteen cards, four tableau piles and a random foundation starting rank. Build foundations up by suit, wrapping from king to ace. Tableau builds down in alternating colours. Turn the stock three at a time.','Play from the reserve whenever possible; it is the key to winning.'],
['fortythieves','Forty Thieves','Card',1,1,'cards','Two decks: ten columns of four cards and eight foundations. Build down by suit in the tableau, one card at a time. The stock is dealt only once.','Empty columns are precious; fill them only with purpose.'],
['accordion','Accordion','Card',1,1,'cards','Deal cards in a line. A card may move onto the card directly to its left or three to its left if they share suit or rank. Try to end with a single pile.','Prefer the three-left move: it shortens the line faster.'],
['tripeaks','Three Peaks','Card',1,1,'cards','Twenty-eight cards form three peaks. Remove uncovered cards that are one higher or lower than the waste card. Turn the stock when stuck. Long streaks score more.','Keep streaks going by planning which peak to dig into.'],
['acesup','Aces Up','Card',1,1,'cards','Four columns. Discard a top card whenever another column\'s top card is higher in the same suit (aces high). Move cards into empty columns. Deal four new cards when stuck. Finish with only the four aces.','Empty columns are your most valuable resource.'],
['beleaguered','Beleaguered Castle','Card',1,1,'cards','Aces start on the foundations; eight rows of six cards fan out beside them. Move the last card of a row onto a card one rank higher of any suit, or into an empty row. Build foundations up by suit.','Empty a row early and use it to reorder cards.'],
['videopoker','Video Poker','Card',1,1,'cards','Jacks or Better. Bet one to five credits, receive five cards, choose which to hold, and draw replacements. Pairs of jacks or better and stronger hands pay out from the table.','Always hold a pair; only hold a single high card if you have nothing else.'],
['higherlower','Higher or Lower','Card',1,1,'cards','Guess whether the next card will be higher or lower than the one showing. Ties count as wrong. Build the longest streak before you run out of lives.','Middle cards are the hardest to call; play the odds.'],
['snap','Snap','Card',1,1,'cards','You and the computer take turns turning cards onto a pile. When the top two cards match in rank, the first to snap takes the pile. Win all the cards.','Watch the pile, not your hand.'],
['ratscrew','Egyptian Ratscrew','Card',1,1,'cards','Take turns turning cards onto a pile. Face cards and aces demand 1–4 cards in payment. Slap the pile on a pair or a sandwich to take it; a wrong slap costs a card. Win all the cards.','Sandwiches are easy to miss: watch the second card from the top.'],
['shutbox','Shut the Box','Dice',1,4,'dice','Tiles 1 to 9 are open. Roll two dice (one when the open tiles total six or less) and shut tiles that add up to the roll. When you cannot, your turn ends and the open tiles are your score. Lowest score wins; shutting every tile wins outright.','Shut high tiles early; small ones are easier to match later.'],
['bunco','Bunco','Dice',2,4,'dice','Six rounds, each with a target number from 1 to 6. Roll three dice: score a point per die showing the target, five for any other triple, or 21 for a Bunco (three of the target). Keep rolling while you score. First to 21 wins the round.','It is pure luck: cheer for Buncos.'],
['pokerdice','Poker Dice','Dice',2,4,'dice','Roll five dice up to three times, holding any you like, to make the best poker hand: five of a kind beats four, then full house, straight, three of a kind, two pairs and one pair. Best hand wins each of three rounds.','Hold pairs and chase full houses rather than straights.'],
['ceelo','Cee-lo','Dice',2,6,'dice','Roll three dice until you get a scoring result: 4-5-6 wins outright, triples rank high, a pair scores the odd die as your point, and 1-2-3 loses. Highest result wins each of five rounds.','There are no choices: enjoy the street-corner classic.'],
['midnight','Midnight','Dice',2,4,'dice','Roll six dice and keep at least one each roll until all six are kept. You must keep a 1 and a 4 to qualify; the other four dice are your score, up to 24. Highest total over three rounds wins.','Grab the 1 and the 4 as soon as they appear, then keep sixes.'],
['beetle','Beetle','Dice',2,4,'dice','Roll a die to draw parts of a beetle: 6 body, 5 head, 4 legs, 3 eyes, 2 antennae, 1 tail. You need the body first and the head before eyes or antennae. Roll again after each useful part. First complete beetle wins.','A children\'s favourite: speed comes from luck alone.'],
['takuzu','Binary Grid','Puzzle',1,1,'grid3','Fill the grid with 0s and 1s. Each row and column has equal numbers of each, no more than two of the same digit sit side by side, and no two rows or columns are identical.','Look for pairs: the cells on either side must be the other digit.'],
['futoshiki','Futoshiki','Puzzle',1,1,'grid3','Place numbers so each row and column contains every number once. Inequality signs between cells must be obeyed.','Chains of signs pin the smallest and largest numbers fast.'],
['skyscrapers','Skyscrapers','Puzzle',1,1,'grid3','Fill each row and column with buildings of heights 1 to N once each. Clues around the edge tell how many buildings you see from that side; taller ones hide shorter ones behind.','A clue of 1 means the tallest building is right next to it.'],
['lightup','Light Up','Puzzle',1,1,'grid3','Place bulbs on white cells so that every white cell is lit. Bulbs shine along rows and columns until blocked by a wall, must not shine on each other, and numbered walls touch exactly that many bulbs.','Start with walls numbered 4 or 0.'],
['hashi','Bridges','Puzzle',1,1,'maze','Connect the islands with horizontal or vertical bridges. Each island\'s number tells how many bridges touch it; two islands can share at most two bridges. Bridges may not cross, and all islands must be connected.','An island needing as many bridges as its neighbours can take is forced.'],
['tents','Tents and Trees','Puzzle',1,1,'grid3','Place one tent next to each tree, horizontally or vertically. Tents never touch each other, even diagonally. Numbers around the grid say how many tents are in each row and column.','Mark cells far from any tree as grass first.'],
['starbattle','Star Battle','Puzzle',1,1,'star','Place one star in every row, column and outlined region. Stars may not touch each other, even diagonally.','Small regions have few spots: solve them first.'],
['killer','Killer Sudoku','Puzzle',1,1,'grid3','Normal sudoku rules, plus the grid is divided into cages whose digits must add up to the number shown, with no repeats in a cage.','Every row, column and box adds to 45; use that to find missing digits.'],
['minisudoku','Mini Sudoku 6×6','Puzzle',1,1,'grid3','Fill the 6×6 grid so every row, column and 2×3 box contains 1 to 6 exactly once.','Scan each box for the only place a digit can go.'],
['trafficjam','Traffic Jam','Puzzle',1,1,'car','Cars slide only forwards and backwards along their length. Move them out of the way so the red car can drive out of the exit on the right.','Work backwards: which cars block the red car, and what blocks them?'],
['floodit','Flood Fill','Puzzle',1,1,'tiles','Starting from the top-left corner, choose a colour to flood your region and absorb neighbouring cells of that colour. Fill the whole board within the move limit.','Pick colours that grab the biggest new areas, not just the nearest.'],
['samegame','Same Game','Puzzle',1,1,'tiles','Click a group of two or more same-coloured blocks to remove it. Blocks fall down and columns shift left. Larger groups score much more; clearing the board earns a bonus.','Build huge groups by removing other colours from between them.'],
['knightstour','Knight\'s Tour','Puzzle',1,1,'board','Move a chess knight so that it visits every square on the board exactly once.','Always move to the square with the fewest onward moves (Warnsdorff\'s rule).'],
['queens','Eight Queens','Puzzle',1,1,'board','Place one queen per row on the board so that no two queens attack each other along rows, columns or diagonals.','Start with a corner-adjacent square in the first row.'],
['watersort','Color Sort','Puzzle',1,1,'tiles','Pour the top colour from one tube into another tube with the same colour on top or into an empty tube. Sort every colour into its own full tube.','Keep one tube empty as long as you can.'],
['untangle','Untangle','Puzzle',1,1,'maze','A tangle of dots and lines is shown. Drag the dots until no two lines cross.','Move dots with many lines first; the rest fall into place.'],
['klotski','Klotski','Puzzle',1,1,'blocks','Slide the blocks within the frame to move the large block out through the gap at the bottom. Blocks cannot be lifted or rotated.','The small squares are your helpers; keep them mobile.'],
['skyclimber','Sky Climber','Arcade',1,1,'ball','Bounce from platform to platform and climb as high as you can. Steer left and right; the screen wraps around. Fall off the bottom and the game is over.','Look ahead for the next platform before you land.'],
['dinorun','Desert Runner','Arcade',1,1,'car','Run across the desert, jumping over cacti and ducking under birds. The pace keeps rising. One hit ends the run.','Jump a little early at higher speeds.'],
['copter','Cave Copter','Arcade',1,1,'ball','Hold to rise and release to fall. Fly through a winding cave that narrows as you go. Touch a wall and the game ends.','Short taps keep you steady; long holds overshoot.'],
['stacker','Tower Stack','Arcade',1,1,'blocks','A block slides back and forth. Tap to drop it onto the tower; anything hanging over the edge is cut off. Perfect drops keep your block full size. Build as high as you can.','Watch the edge of the block below, not the moving block.'],
['fruitslice','Fruit Slicer','Arcade',1,1,'target','Fruit is tossed into the air. Swipe through it to slice it. Missing fruit costs a life, and slicing a bomb ends the game.','Swipe through several fruits in one stroke.'],
['airhockey','Air Hockey','Arcade',1,1,'ball','Move your striker to hit the puck into the computer\'s goal while defending your own. First to seven points wins.','Bank shots off the side walls are hard to defend.'],
['bowling','Bowling','Arcade',1,1,'ball','Aim, set your power and roll at ten pins. Ten frames, with bonuses for strikes and spares, make up a game scored to 300.','Aim just off centre for the best chance of a strike.'],
['darts','Darts 301','Arcade',1,1,'target','Start at 301 and throw three darts per turn, subtracting your score. You must finish exactly on zero with a double; going below zero, to one or finishing without a double is a bust.','Leave yourself an even number to finish on a double.'],
['hoops','Hoop Shot','Arcade',1,1,'ball','Flick the basketball upward toward the hoop. Score as many baskets as you can in 60 seconds. At higher levels the hoop moves.','A higher arc drops through the rim more often.'],
['mazechomp','Maze Muncher','Arcade',1,1,'maze','Guide Jelly through the maze collecting every gem while spinning sparks chase you. Green stars make the sparks harmless for a short time so you can bump them away. Collect all the gems to win.','Save the green stars for when sparks are close.'],
['galaxy','Galaxy Shooter','Arcade',1,1,'star','Pilot your ship through waves of enemy fighters. Hold to fire, dodge their shots and survive as long as you can.','Keep moving: standing still is how bullets find you.'],
['aimtrainer','Target Practice','Arcade',1,1,'target','Targets appear and shrink. Tap them before they vanish; faster hits score more and misses cost points. You have 30 seconds.','Move your eyes, not just your hand: look for the next target early.'],
['honeycomb','Honeycomb Words','Word',1,1,'letters','Make words of four or more letters from the seven letters shown, always using the centre letter. Letters may be reused. Longer words score more, and using all seven letters earns a bonus.','Try common endings like -ING and -ED with the centre letter.'],
['wordladder','Word Ladder','Word',1,1,'letters','Change the starting word into the target word one letter at a time. Every step must be a real word. Use as few steps as you can.','Change vowels first; they connect the most words.'],
['cryptogram','Cryptogram','Word',1,1,'letters','A saying has been encoded by swapping each letter for another. Work out the substitutions to reveal the message.','Single-letter words are usually A or I; THE is the most common word.'],
['typing','Typing Race','Word',1,1,'letters','Type the words shown as fast and accurately as you can for 60 seconds. Press space after each word. Your speed is measured in words per minute.','Accuracy first; speed follows.'],
['wordchain','Word Chain','Word',2,4,'letters','Each word must start with the last letter of the previous word and must not have been used before. Words need three or more letters. Fail to play and you take a strike; three strikes and you are out.','End your words with awkward letters like X or Z.'],
['twentyq','Twenty Questions','Party',1,1,'target','Think of an animal and answer the computer\'s yes-or-no questions. It tries to guess your animal in twenty questions or fewer. Stump it to win.','Pick an unusual animal to beat the computer.'],
['bulls','Bulls and Cows','Puzzle',1,1,'pegs','Guess the secret number whose digits are all different. Bulls are right digits in the right place; cows are right digits in the wrong place. Crack it in twelve guesses.','Use your first guesses to find which digits are in the number.'],
['game24','Make 24','Puzzle',1,1,'tiles','Use all four numbers once each, with addition, subtraction, multiplication and division, to make exactly 24. Eight rounds against the clock.','Look for 3×8, 4×6 and 2×12 first.'],
['bingo','Bingo','Party',1,1,'target','Numbers from 1 to 75 are called. Mark them on your card. Claim bingo with a complete row, column or diagonal before the computer\'s cards do.','Keep an eye on the centre: it is free and part of four lines.'],
];

// Seat limits raised where the rules and the engine handle more players (tested up to these counts).
const MAX_SEATS = { ladders:8, crazy8:8, holdem:8, oldmaid:8, gofish:8, president:8, yacht:8, pig:8, liars:8, farkle:8, shipcap:8, mexico:8, wordtiles:8, ghost:8, cheat:8, scat:8, sixgolf:8, knockout:7, bunco:8, pokerdice:8, ceelo:8, midnight:8, beetle:8, wordchain:8, shutbox:8, ohhell:7, durak:6 };
const CATALOG = CATALOG_RAW.map(([id,name,cat,minP,maxP,glyph,rules,tip],i)=>({id,name,cat,minP,maxP: maxP === 1 ? 8 : (MAX_SEATS[id] || maxP),glyph,rules,tip,rank:i,solo: maxP === 1}));
const GAME = Object.fromEntries(CATALOG.map(g=>[g.id,g]));
const TOP = ['chess','c4','klondike','snake','blocks','checkers','chinesecheckers','sudoku','ttt','mines','g2048','reversi','crazy8','yacht','go','seabattle','five'];
const CATS = ['Board','Card','Dice','Puzzle','Word','Arcade','Party'];
const CAT_COLOR = {Board:'#0f5a43',Card:'#b3261e',Dice:'#7a3fb0',Puzzle:'#1a62b8',Word:'#a35a00',Arcade:'#d1342b',Party:'#0f7d79'};
